using RutaCero.Domain.Reconciliation;using RutaCero.Domain.Transactions;using RutaCero.Domain.ValueObjects;
namespace RutaCero.Domain.Tests;
public sealed class ReconciliationTests
{
 [Fact]public void Calculates_balance_with_incoming_and_outgoing_movements(){var user=Guid.NewGuid();var account=Guid.NewGuid();var other=Guid.NewGuid();var date=new DateOnly(2026,8,19);var now=DateTimeOffset.UtcNow;var items=new[]{new Transaction(user,account,null,null,TransactionType.Expense,new(100,Currency.HNL),date,"Compra",now),new Transaction(user,other,account,null,TransactionType.Transfer,new(250,Currency.HNL),date,"Transferencia",now)};Assert.Equal(1150,new BalanceReconciliationService().Calculate(new(1000,Currency.HNL),account,items).Amount);}
 [Fact]public void Compensated_transfer_subtracts_origin_and_adds_destination(){var user=Guid.NewGuid();var origin=Guid.NewGuid();var destination=Guid.NewGuid();var group=Guid.NewGuid();var date=new DateOnly(2026,8,23);var now=DateTimeOffset.UtcNow;var items=new[]{new Transaction(user,origin,destination,null,TransactionType.Transfer,new(300,Currency.HNL),date,"Transferencia",now,group,TransferDirection.Outgoing),new Transaction(user,destination,origin,null,TransactionType.Transfer,new(300,Currency.HNL),date,"Transferencia",now,group,TransferDirection.Incoming)};var service=new BalanceReconciliationService();Assert.Equal(700,service.Calculate(new(1000,Currency.HNL),origin,items).Amount);Assert.Equal(500,service.Calculate(new(200,Currency.HNL),destination,items).Amount);}
}
